#import "SideStoreStrings.h"

static NSDictionary<NSString *, NSString *> *gExact;
static NSArray<NSArray *> *gPatterns;

NSString *SSTLookupExact(NSString *s) {
    return s ? gExact[s] : nil;
}

NSString *SSTLookupPattern(NSString *s) {
    if (!s.length || !gPatterns.count) return nil;
    for (NSArray *pair in gPatterns) {
        NSRegularExpression *re = pair[0];
        NSTextCheckingResult *m = [re firstMatchInString:s options:0 range:NSMakeRange(0, s.length)];
        if (!m) continue;
        NSMutableString *out = [pair[1] mutableCopy];
        for (NSInteger i = m.numberOfRanges - 1; i >= 1; i--) {
            NSRange r = [m rangeAtIndex:i];
            if (r.location == NSNotFound) continue;
            [out replaceOccurrencesOfString:[NSString stringWithFormat:@"$%ld", (long)i]
                                    withString:[s substringWithRange:r]
                                       options:0
                                         range:NSMakeRange(0, out.length)];
        }
        return out;
    }
    return nil;
}

